package wallet

import "time"

// Balances 表示账户当前的资金状态，单位均为最小货币单位的整数。
type Balances struct {
	// Available 为可用于新预留的余额（初始余额减去已预留和已扣减）。
	Available int64
	// Reserved 为已受理但尚未结算或取消的请求所预留的费用总额。
	Reserved int64
}

// AccountView 是账户的只读视图。
type AccountView struct {
	ID        string
	Balances  Balances
	CreatedAt time.Time
}

// SessionState 描述会话状态。
type SessionState int

const (
	// SessionActive 有效会话。
	SessionActive SessionState = iota
	// SessionRevoked 已被主动吊销。
	SessionRevoked
)

// SessionView 是会话的只读视图。
type SessionView struct {
	ID        string
	AccountID string
	DeviceID  string
	ExpiresAt time.Time
	State     SessionState
	CreatedAt time.Time
}

// PolicySpec 定义一条代付策略。
//
// 多个使用账户共享同一累计额度。时间窗为 [StartsAt, EndsAt)。
type PolicySpec struct {
	// ID 为策略唯一编号，留空时拒绝保存。
	ID string
	// PayerAccountID 为出资账户。
	PayerAccountID string
	// AllowedAccountIDs 为允许发起代付的使用账户列表，不能为空。
	AllowedAccountIDs []string
	// Operation 为允许的操作类型，不能为空。
	Operation string
	// Payee 为允许的收款方，不能为空。
	Payee string
	// StartsAt 为授权时间窗起点（含）。
	StartsAt time.Time
	// EndsAt 为授权时间窗终点（不含）。
	EndsAt time.Time
	// MaxPerRequest 为单次费用上限，必须为正。
	MaxPerRequest int64
	// MaxTotal 为所有使用账户共享的累计费用上限，必须为正。
	MaxTotal int64
	// ApprovalThreshold 为大额审批门槛：预估费用严格超过此值的申请进入
	// 待审批，由出资账户审批通过后才预留。零表示关闭审批，申请直接预留；
	// 不得为负，且不得超过单次费用上限。
	ApprovalThreshold int64
	// ApprovalWait 为待审批请求的最长等待时长（自提交时刻起算）。
	// 审批开启（ApprovalThreshold 为正）时必须为正；关闭时忽略。
	ApprovalWait time.Duration
	// MaxReserveDuration 为已预留请求的最长预留时长：自直接受理时刻，或
	// 待审批请求被批准成功的时刻起算（等待审批的时间不计入）。零表示关闭
	// 预留超时，已预留费用只在结算或取消时释放；不得为负。
	MaxReserveDuration time.Duration
}

// PolicyView 是策略的只读视图。
type PolicyView struct {
	PolicySpec
	// ReservedTotal 为当前处于预留中的费用总额（占用累计额度）。
	ReservedTotal int64
	// SpentTotal 为已结算扣除的累计费用。
	SpentTotal int64
	// Deactivated 表示策略是否已被出资账户主动停用；新保存的策略为 false。
	// 停用不可撤销，停用后策略不再受理新申请，编号也不能重新保存为新策略。
	Deactivated bool
	// DeactivatedAt 为首次停用时间；未停用时为零值。
	DeactivatedAt time.Time
	// DeactivatorAccountID 为执行停用的出资账户；未停用时为空。
	DeactivatorAccountID string
	// DeactivateReason 为去掉首尾空白后的停用理由；未停用时为空。
	DeactivateReason string
}

// RequestState 描述代付请求的生命周期状态。
type RequestState int

const (
	// RequestReserved 已受理并完成费用预留，等待结算或取消。
	RequestReserved RequestState = iota
	// RequestSettled 已按实际费用结算。
	RequestSettled
	// RequestCancelled 未结算即取消，预留已全部退回。
	RequestCancelled
	// RequestPendingApproval 预估费用超过审批门槛，等待出资账户审批；
	// 此状态不冻结余额、不占用共享累计额度。
	RequestPendingApproval
	// RequestRejected 已被拒绝（审批拒绝、申请会话在等待期限内被吊销或
	// 策略被停用），终态。已到等待截止时刻后才吊销会话的请求不进入此态，
	// 而是 RequestExpired。
	RequestRejected
	// RequestExpired 待审批超过等待期限未获批准，终态。
	RequestExpired
	// RequestReservationExpired 已预留请求超过策略的最长预留时长仍未结算或
	// 取消，终态。预留已在截止时刻全额自动退回，与待审批等待过期
	// （RequestExpired）区分。
	RequestReservationExpired
)

// RequestInput 是代付申请内容。
type RequestInput struct {
	// PolicyID 指定适用策略。
	PolicyID string
	// RequestID 为使用账户维度的幂等请求编号。
	RequestID string
	// AccountID 为发起申请的使用账户。
	AccountID string
	// SessionID 为该账户绑定设备的有效会话。
	SessionID string
	// DeviceID 为当前设备，必须与会话绑定设备一致。
	DeviceID string
	// Operation 为操作类型，必须与策略一致。
	Operation string
	// Payee 为收款方，必须与策略一致。
	Payee string
	// EstimatedFee 为预估费用，必须为正，受理后按此金额预留。
	EstimatedFee int64
}

// RequestView 是代付请求的只读视图。
type RequestView struct {
	PolicyID       string
	RequestID      string
	AccountID      string
	PayerAccountID string
	Operation      string
	Payee          string
	EstimatedFee   int64
	ActualFee      int64
	State          RequestState
	CreatedAt      time.Time
	SettledAt      time.Time
	// WaitDeadline 为待审批期限（提交时刻 + 等待时长、策略结束时间、
	// 申请会话到期时间三者中的最早值）；非待审批请求为零值。
	WaitDeadline time.Time
	// ReservedAt 为费用实际预留完成的时刻：直接受理的请求为受理时刻，
	// 批准后预留的请求为批准成功时刻。从未预留（待审批、被拒、待审批过期、
	// 待审批取消）时为零值；预留超时后仍保留该时刻。
	ReservedAt time.Time
	// ReserveDuration 为受理/批准时适用的策略最长预留时长；策略未启用预留
	// 超时（时长为零）或请求从未预留时为零。
	ReserveDuration time.Duration
	// ReserveDeadline 为启用预留超时时的截止时刻（预留时刻 + 最长预留时长）；
	// 未启用或请求从未预留时为零值。结算或取消不会改变该时刻。
	ReserveDeadline time.Time
	// ReserveExpiredAt 为预留因超时自动释放的时刻；记录的是截止时刻本身，
	// 而非稍后实际处理（查询或新申请）的时刻。尚未超时或未启用时为零值。
	ReserveExpiredAt time.Time
	// DecidedAt 为审批决定时间（批准、拒绝或过期的时刻）；未决定时为零值。
	DecidedAt time.Time
	// ApproverAccountID 为作出批准或拒绝决定的出资账户；未决定时为空。
	ApproverAccountID string
	// RejectReason 为拒绝原因（审批拒绝、会话吊销或策略停用）；未拒绝时为空。
	RejectReason string
}

// LedgerKind 标识账本记录类型。
type LedgerKind int

const (
	// LedgerReserve 预留：冻结预估费用。
	LedgerReserve LedgerKind = iota
	// LedgerSettle 扣减：结算时实际扣除的费用。
	LedgerSettle
	// LedgerRefund 退回：结算差额或取消时退回的预留。
	LedgerRefund
	// LedgerRejection 申请被拒绝或待审批被拒的留痕，不涉及任何金额变动。
	LedgerRejection
	// LedgerPendingApproval 申请进入待审批的状态留痕，无金额变动。
	LedgerPendingApproval
	// LedgerApproval 待审批被批准的状态留痕，无金额变动；批准带来的
	// 预留另记 LedgerReserve。
	LedgerApproval
	// LedgerCancellation 待审批请求被取消的状态留痕，无金额变动
	// （已预留请求的取消仍记 LedgerRefund）。
	LedgerCancellation
	// LedgerExpiration 待审批超过期限未获批准的状态留痕，无金额变动。
	LedgerExpiration
	// LedgerPolicyDeactivation 策略被出资账户主动停用的留痕，无金额变动；
	// AccountID 为出资账户，PolicyID 为被停用的策略，RequestID 为空。
	LedgerPolicyDeactivation
	// LedgerReservationExpiration 已预留请求超过最长预留时长被自动退回的
	// 状态留痕，无金额变动；AccountID 为发起申请的使用账户，关联请求编号。
	// 全额退款另记一条 LedgerRefund（AccountID 为出资账户，金额为预留全额）。
	LedgerReservationExpiration
)

// LedgerEntry 是一条账本记录。
type LedgerEntry struct {
	// Kind 为记录类型。
	Kind LedgerKind
	// AccountID 为资金发生变动的出资账户（预留、扣减、退回）；
	// 无金额变动的状态记录（待审批、批准、拒绝、取消、过期）中
	// 为发起申请的使用账户，用于关联使用账户。
	AccountID string
	// RequestID 为关联的代付请求编号。
	RequestID string
	// PolicyID 为关联的策略编号；仅策略停用等不针对具体请求的记录使用，
	// 其余记录为空（请求记录可用请求上的策略编号关联）。
	PolicyID string
	// Amount 为金额（最小货币单位，非负）；状态记录为 0。
	Amount int64
	// Reason 为拒绝原因或补充说明。
	Reason string
	At     time.Time
}

package wallet

import "errors"

// 资金与会话相关错误。
var (
	// ErrInvalidAmount 金额非法（负数等）。
	ErrInvalidAmount = errors.New("wallet: invalid amount")
	// ErrAccountExists 账户编号已存在。
	ErrAccountExists = errors.New("wallet: account already exists")
	// ErrAccountNotFound 账户不存在。
	ErrAccountNotFound = errors.New("wallet: account not found")
	// ErrEmptyAccountID 账户编号为空。
	ErrEmptyAccountID = errors.New("wallet: empty account id")
	// ErrInvalidArgument 必填参数缺失。
	ErrInvalidArgument = errors.New("wallet: invalid argument")
	// ErrSessionExists 会话编号已存在。
	ErrSessionExists = errors.New("wallet: session already exists")

	// ErrSessionNotFound 会话不存在。
	ErrSessionNotFound = errors.New("wallet: session not found")
	// ErrSessionAccountMismatch 会话不属于申请时提供的账户。
	ErrSessionAccountMismatch = errors.New("wallet: session belongs to another account")
	// ErrSessionDeviceMismatch 会话绑定的设备与申请设备不符。
	ErrSessionDeviceMismatch = errors.New("wallet: session device mismatch")
	// ErrSessionExpired 会话已到期（含到期时刻本身）。
	ErrSessionExpired = errors.New("wallet: session expired")
	// ErrSessionRevoked 会话已被吊销。
	ErrSessionRevoked = errors.New("wallet: session revoked")

	// ErrPolicyExists 策略编号已存在。
	ErrPolicyExists = errors.New("wallet: policy already exists")
	// ErrPolicyNotFound 策略不存在。
	ErrPolicyNotFound = errors.New("wallet: policy not found")
	// ErrPolicyInvalid 策略定义非法（限额、时间窗、账户等）。
	ErrPolicyInvalid = errors.New("wallet: invalid policy")
	// ErrPolicyDenied 申请不满足策略授权条件（默认拒绝）。
	ErrPolicyDenied = errors.New("wallet: request denied by policy")
	// ErrPolicyDeactivated 策略已被出资账户主动停用，不再受理新申请。
	ErrPolicyDeactivated = errors.New("wallet: policy is deactivated")
	// ErrNotPolicyOwner 停用会话不存在、不属于该策略的出资账户、设备不符、
	// 已过期或已吊销，调用方无权停用该策略。
	ErrNotPolicyOwner = errors.New("wallet: not authorized to deactivate this policy")
	// ErrInsufficientBalance 出资账户可用余额不足。
	ErrInsufficientBalance = errors.New("wallet: insufficient available balance")
	// ErrQuotaExceeded 超出策略单次或累计费用上限。
	ErrQuotaExceeded = errors.New("wallet: policy quota exceeded")

	// ErrRequestNotFound 请求不存在。
	ErrRequestNotFound = errors.New("wallet: request not found")
	// ErrConflict 幂等键相同但申请内容或结算金额不一致。
	ErrConflict = errors.New("wallet: conflicting request")
	// ErrAlreadySettled 请求已结算，不能取消或再次按不同金额结算。
	ErrAlreadySettled = errors.New("wallet: request already settled")
	// ErrAlreadyCancelled 请求已取消，不能结算。
	ErrAlreadyCancelled = errors.New("wallet: request already cancelled")
	// ErrSettleTooLarge 结算实际费用超过预留的预估费用。
	ErrSettleTooLarge = errors.New("wallet: actual fee exceeds estimated fee")

	// ErrNotApprover 审批会话不属于出资账户、设备不符、已过期或已吊销，
	// 调用方无权审批该请求。
	ErrNotApprover = errors.New("wallet: not authorized to approve this request")
	// ErrApprovalExpired 待审批已超过等待期限，不能再批准。
	ErrApprovalExpired = errors.New("wallet: approval period expired")
	// ErrRequestNotPending 请求不处于待审批状态，不能批准或拒绝。
	ErrRequestNotPending = errors.New("wallet: request is not pending approval")
	// ErrRequestNotReserved 请求不处于已预留状态，不能结算或（在拒绝、
	// 过期终态下）取消。
	ErrRequestNotReserved = errors.New("wallet: request is not reserved")
	// ErrReservationExpired 请求的预留已超过最长预留时长自动退回，终态。
	// 此时结算（即使实际费用非负）也不能再扣款；取消与同号同内容申请幂等
	// 返回已有超时结果。
	ErrReservationExpired = errors.New("wallet: reservation expired")
)

