92		ID                   string       `json:"id"`
93		PayerAccountID       string       `json:"payer_account_id"`
94		AllowedAccountIDs    []string     `json:"allowed_account_ids"`
95		Operation            string       `json:"operation"`
96		Payee                string       `json:"payee"`
97		StartsAt             timeJSON     `json:"starts_at"`
98		EndsAt               timeJSON     `json:"ends_at"`
99		MaxPerRequest        int64        `json:"max_per_request"`
100		MaxTotal             int64        `json:"max_total"`
101		ApprovalThreshold    int64        `json:"approval_threshold"`
102		ApprovalWait         durationJSON `json:"approval_wait_nanos"`
103		MaxReserveDuration   durationJSON `json:"max_reserve_duration_nanos"`
104		ReservedTotal        int64        `json:"reserved_total"`
105		SpentTotal           int64        `json:"spent_total"`
106		Deactivated          bool         `json:"deactivated"`
107		DeactivatedAt        timeJSON     `json:"deactivated_at"`
108		DeactivatorAccountID string       `json:"deactivator_account_id"`
109		DeactivateReason     string       `json:"deactivate_reason"`
110	}
111	
112	type requestBackupV1 struct {
113		PolicyID          string       `json:"policy_id"`
114		RequestID         string       `json:"request_id"`
115		AccountID         string       `json:"account_id"`
116		PayerAccountID    string       `json:"payer_account_id"`
117		SessionID         string       `json:"session_id"`
118		Operation         string       `json:"operation"`
119		Payee             string       `json:"payee"`
120		EstimatedFee      int64        `json:"estimated_fee"`
121		ActualFee         int64        `json:"actual_fee"`
122		State             int          `json:"state"`
123		CreatedAt         timeJSON     `json:"created_at"`
124		SettledAt         timeJSON     `json:"settled_at"`
