266	// Session 查询会话视图。
267	func (w *Wallet) Session(id string) (SessionView, error) {
268		w.mu.Lock()
269		defer w.mu.Unlock()
270	
271		sess, ok := w.sessions[id]
272		if !ok {
273			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
274		}
275		return sess.view(), nil
276	}
