14	// backupSetup 构造一个覆盖全部状态的钱包：
15	//   - 账户 payer/u1/u2；会话 s1、s2（使用）、sa（出资审批）、s3（吊销）、
16	//     s4（已到期）；
17	//   - p-app 开审批（等待 5 分钟，预留超时 10 小时）、p-to 开预留超时
18	//     （1 分钟、无审批）、p-notime 不启用任何超时、p-deact 已停用；
19	//   - 请求覆盖直接预留、已结算、已预留后取消、待审批、已批准预留、被拒、
20	//     待审批取消、待审批过期、预留超时，以及同号不同使用账户；
21	//   - 账本含未被受理申请（空字段、未知账户、未知会话）的拒绝记录。
22	//
23	// 所有存活请求的计时基准都在 t0；构造终态时临时拨快时钟后再拨回 t0。
24	func backupSetup(t *testing.T) (*Wallet, *clock) {
25		t.Helper()
26		w, c := newTestWallet() // t0 = 2026-01-01 12:00:00 UTC
27		t0 := c.t
28	
29		mustAccount(t, w, "payer", 1000)
30		mustAccount(t, w, "u1", 0)
31		mustAccount(t, w, "u2", 0)
32		if _, err := w.CreateSession("s1", "u1", "dev1", t0.Add(time.Hour)); err != nil {
33			t.Fatal(err)
34		}
35		if _, err := w.CreateSession("s2", "u2", "dev2", t0.Add(time.Hour)); err != nil {
36			t.Fatal(err)
37		}
38		if _, err := w.CreateSession("sa", "payer", "deva", t0.Add(2*time.Hour)); err != nil {
39			t.Fatal(err)
40		}
41		if _, err := w.CreateSession("s3", "u1", "dev3", t0.Add(time.Hour)); err != nil {
42			t.Fatal(err)
43		}
44		if _, err := w.CreateSession("s4", "u2", "dev4", t0.Add(-time.Hour)); err != nil {
45			t.Fatal(err)
46		}
47	
48		mkPolicy := func(id string, threshold int64, wait, reserve time.Duration, per, total int64) PolicySpec {
49			return PolicySpec{
50				ID:                 id,
51				PayerAccountID:     "payer",
52				AllowedAccountIDs:  []string{"u1", "u2"},
53				Operation:          "charge",
54				Payee:              "shop",
55				StartsAt:           t0.Add(-time.Hour),
56				EndsAt:             t0.Add(time.Hour),
57				MaxPerRequest:      per,
58				MaxTotal:           total,
59				ApprovalThreshold:  threshold,
60				ApprovalWait:       wait,
61				MaxReserveDuration: reserve,
62			}
63		}
64		if err := w.SavePolicy(mkPolicy("p-app", 10, 5*time.Minute, 10*time.Hour, 100, 1000)); err != nil {
65			t.Fatal(err)
66		}
67		if err := w.SavePolicy(mkPolicy("p-to", 0, 0, time.Minute, 100, 1000)); err != nil {
68			t.Fatal(err)
69		}
70		if err := w.SavePolicy(mkPolicy("p-notime", 0, 0, 0, 100, 1000)); err != nil {
71			t.Fatal(err)
72		}
73		if err := w.SavePolicy(mkPolicy("p-deact", 0, 0, 0, 100, 1000)); err != nil {
74			t.Fatal(err)
75		}
76		if _, err := w.DeactivatePolicy("p-deact", "sa", "deva", "stop it"); err != nil {
77			t.Fatal(err)
78		}
79		if err := w.RevokeSession("s3"); err != nil {
80			t.Fatal(err)
81		}
82	
83		apply := func(policy, account, sess, dev, rid string, fee int64) RequestView {
84			in := RequestInput{
85				PolicyID: policy, RequestID: rid, AccountID: account, SessionID: sess,
86				DeviceID: dev, Operation: "charge", Payee: "shop", EstimatedFee: fee,
87			}
88			v, err := w.Apply(in)
89			if err != nil {
90				t.Fatalf("apply %s/%s: %v", account, rid, err)
91			}
92			return v
93		}
94	
95		// 直接预留（p-app，费用 5 不超门槛）。
96		apply("p-app", "u1", "s1", "dev1", "direct", 5)
97		// 已结算（实际 3）。
98		apply("p-app", "u1", "s1", "dev1", "settled", 5)
99		if _, err := w.Settle("u1", "settled", 3); err != nil {
100			t.Fatal(err)
101		}
102		// 已预留后取消。
103		apply("p-app", "u1", "s1", "dev1", "cancel-reserved", 5)
104		if _, err := w.Cancel("u1", "cancel-reserved"); err != nil {
105			t.Fatal(err)
106		}
107		// 待审批（恢复时才到期）。
108		apply("p-app", "u1", "s1", "dev1", "pending-due", 20)
109		// 批准后预留。
110		apply("p-app", "u2", "s2", "dev2", "approved", 20)
111		if _, err := w.Approve("u2", "approved", "sa", "deva"); err != nil {
112			t.Fatal(err)
113		}
114		// 审批拒绝。
115		apply("p-app", "u2", "s2", "dev2", "rejected", 20)
116		if _, err := w.Reject("u2", "rejected", "sa", "deva", "no way"); err != nil {
117			t.Fatal(err)
118		}
119		// 待审批取消。
120		apply("p-app", "u2", "s2", "dev2", "cancel-pending", 20)
121		if _, err := w.Cancel("u2", "cancel-pending"); err != nil {
122			t.Fatal(err)
123		}
124		// 待审批等待过期（终态）：临时拨快时钟触发后拨回。
125		apply("p-app", "u2", "s2", "dev2", "pending-expired", 20)
126		c.t = t0.Add(6 * time.Minute)
127		if r, err := w.Request("u2", "pending-expired"); err != nil || r.State != RequestExpired {
128			t.Fatalf("pending-expired state = %v err = %v", r.State, err)
129		}
130		c.t = t0
131		// 预留超时（终态，释放时刻必须是原截止时刻 t0+1m）：拨快触发后拨回。
132		apply("p-to", "u1", "s1", "dev1", "resv-expired", 5)
133		c.t = t0.Add(2 * time.Minute)
134		if r, err := w.Request("u1", "resv-expired"); err != nil || r.State != RequestReservationExpired {
135			t.Fatalf("resv-expired state = %v err = %v", r.State, err)
136		}
137		c.t = t0
138		// 恢复时才到期的预留（截止 t0+1m，导出时仍存活）。
139		apply("p-to", "u1", "s1", "dev1", "resv-due", 5)
140		// 关闭预留超时：很久以后仍等待结算或取消。
141		apply("p-notime", "u1", "s1", "dev1", "no-timeout", 5)
142		// 同号不同使用账户：分别识别。
143		apply("p-notime", "u1", "s1", "dev1", "same-id", 5)
144		apply("p-notime", "u2", "s2", "dev2", "same-id", 5)
145	
146		// 未被受理申请的拒绝记录：空字段、未知账户、未知会话各一条。
147		if _, err := w.Apply(RequestInput{EstimatedFee: -1}); !errors.Is(err, ErrInvalidAmount) {
148			t.Fatalf("empty/invalid apply err = %v", err)
149		}
150		if _, err := w.Apply(RequestInput{
151			PolicyID: "p-app", RequestID: "ghost-rid", AccountID: "ghost",
152			SessionID: "s1", DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 5,
153		}); !errors.Is(err, ErrAccountNotFound) {
154			t.Fatalf("ghost account apply err = %v", err)
155		}
156		if _, err := w.Apply(RequestInput{
157			PolicyID: "p-app", RequestID: "no-session", AccountID: "u1",
158			SessionID: "missing", DeviceID: "dev1", Operation: "charge", Payee: "shop", EstimatedFee: 5,
159		}); !errors.Is(err, ErrSessionNotFound) {
160			t.Fatalf("missing session apply err = %v", err)
161		}
162	
163		return w, c
164	}
