166	// exportAndRestoreAt 在指定时刻导出（导出时钟由 c 控制）并用指定恢复时刻
167	// 恢复成新钱包。
168	func exportAndRestoreAt(t *testing.T, w *Wallet, restoreTime time.Time) *Wallet {
169		t.Helper()
