223	func TestExportAddsNoLedgerEntryAndIsDeterministic(t *testing.T) {
224		w, _ := backupSetup(t)
225		before := len(w.Ledger())
226		d1, err := w.Export()
227		if err != nil {
228			t.Fatal(err)
229		}
230		if got := len(w.Ledger()); got != before {
