379	func TestRestoreProcessesDueAtRestoreTime(t *testing.T) {
380		w, c := backupSetup(t)
381		t0 := c.t
382		// 导出时刻 t0：pending-due（截止 t0+5m）与 resv-due（截止 t0+1m）均未到期。
383		data, err := w.Export()
384		if err != nil {
385			t.Fatal(err)
386		}
387		srcBal, _ := w.Balance("payer")
388	
389		// 恢复时刻 t0+30m：待审批已过期；预留已超时全额退回，释放时间仍是 t0+1m。
390		w2, err := restoreAt(data, t0.Add(30*time.Minute))
391		if err != nil {
392			t.Fatalf("restore: %v", err)
393		}
394	
395		pd, _ := w2.Request("u1", "pending-due")
396		if pd.State != RequestExpired {
397			t.Fatalf("pending-due state = %v, want expired", pd.State)
398		}
399		if pd.DecidedAt.IsZero() {
400			t.Fatal("expired request must record decided_at")
401		}
402		rd, _ := w2.Request("u1", "resv-due")
403		if rd.State != RequestReservationExpired {
404			t.Fatalf("resv-due state = %v, want reservation expired", rd.State)
405		}
406		if want := t0.Add(time.Minute); !rd.ReserveExpiredAt.Equal(want) {
407			t.Fatalf("release time = %v, want original deadline %v (not restore time)", rd.ReserveExpiredAt, want)
408		}
409		// 退回的 5 立即可用；预留余额相应下降。
410		gotBal, _ := w2.Balance("payer")
411		if gotBal.Available != srcBal.Available+5 || gotBal.Reserved != srcBal.Reserved-5 {
412			t.Fatalf("balance after restore = %+v, want available %d reserved %d", gotBal, srcBal.Available+5, srcBal.Reserved-5)
413		}
414		// 账本：在原账本之后追加 预留超时退款 + 超时记录 + 待审批过期记录。
415		var kinds []LedgerKind
416		for _, e := range w2.Ledger() {
417			switch {
418			case e.Kind == LedgerRefund && e.RequestID == "resv-due":
419				kinds = append(kinds, LedgerRefund)
420				if e.Amount != 5 || !e.At.Equal(t0.Add(time.Minute)) {
421					t.Fatalf("resv-due refund entry = %+v", e)
422				}
423				if e.AccountID != "payer" {
424					t.Fatalf("refund account = %q, want payer", e.AccountID)
425				}
426			case e.Kind == LedgerReservationExpiration && e.RequestID == "resv-due":
427				kinds = append(kinds, LedgerReservationExpiration)
428				if !e.At.Equal(t0.Add(time.Minute)) {
429					t.Fatalf("timeout entry at %v, want deadline", e.At)
430				}
431			case e.Kind == LedgerExpiration && e.RequestID == "pending-due":
432				kinds = append(kinds, LedgerExpiration)
433			}
434		}
435		if len(kinds) != 3 {
436			t.Fatalf("expected 3 new entries, got %v", kinds)
437		}
438	
439		// 未到期（相对 t0+30m）的请求继续等待或预留。
440		if d, _ := w2.Request("u1", "direct"); d.State != RequestReserved {
441			t.Fatalf("direct state = %v, want still reserved", d.State)
442		}
443		if a, _ := w2.Request("u2", "approved"); a.State != RequestReserved {
444			t.Fatalf("approved state = %v, want still reserved", a.State)
445		}
446		// 既有终态不改写。
447		re, _ := w2.Request("u1", "resv-expired")
448		if !re.ReserveExpiredAt.Equal(t0.Add(time.Minute)) {
449			t.Fatalf("pre-existing timeout release time rewritten: %v", re.ReserveExpiredAt)
450		}
451	}
