	if err != nil {
		t.Fatal(err)
	}
	w3, err := restoreAt(data, t0)
	if err != nil {
		t.Fatal(err)
	}

	// 在 w2 结算 no-timeout（实际 1），w3、原钱包不受影响。
	if _, err := w2.Settle("u1", "no-timeout", 1); err != nil {
