		}
		if r.State != RequestReserved || r.ActualFee != 0 {
			t.Fatalf("%s mutated by w2 settle: %+v", name, r)
		}
	}
	// 原钱包继续操作不影响恢复出的钱包。
	if _, err := w.Cancel("u1", "direct"); err != nil {
